top: 0;
left: 0;
width: 100%;
height: 100%;
zindex: 0;
opacity: 0.4;
pointerevents: none;
background: radialgradient(circle at 50% 50%, 2b0014 0%, 000000 100%);
backgroundsize: 200% 200%;
animation: gradientShift 15s ease infinite;
}
@keyframes gradientShift {
0% { backgroundposition: 0% 50%; }
50% { backgroundposition: 100% 50%; }
100% { backgroundposition: 0% 50%; }
}
tubescanvas {
position: fixed;
top: 0;
left: 0;
width: 100%;
height: 100%;
zindex: 1;
opacity: 0.8;
pointerevents: none;
display: none;
}
applicationcontainer {
position: relative;
width: 100%;
height: 100%;
zindex: 2;
display: flex;
flexdirection: column;
transition: transform 0.6s var(easeapple), filter 0.6s var(easeapple);
background: transparent;
}
applicationcontainer.minimized {
transform: scale(0.92) translateY(10px);
filter: blur(12px) brightness(0.7);
pointerevents: none;
borderradius: 20px;
overflow: hidden;
border: 1px solid var(accentblue);
boxshadow: 0 0 30px rgba(255, 20, 147, 0.3);
}
.headerbar {
position: absolute;
top: 0;
left: 0;
width: 100%;
height: calc(60px + var(safetop));
paddingtop: var(safetop);
background: rgba(20, 0, 5, 0.4);
backdropfilter: blur(var(blurmd));
webkitbackdropfilter: blur(var(blurmd));
borderbottom: 1px solid var(bordersubtle);
display: flex;
alignitems: center;
justifycontent: center;
zindex: 10;
boxshadow: 0 4px 30px rgba(255, 20, 147, 0.15);
transition: background 0.3s ease;
}
.headertitle {
fontfamily: 'Cinzel', serif;
fontsize: 18px;
fontweight: 700;
letterspacing: 0.15em;
texttransform: uppercase;
background: var(accentgradienttext);
webkitbackgroundclip: text;
webkittextfillcolor: transparent;
textshadow: 0 0 20px rgba(255, 20, 147, 0.6);
}
.headerleftaction {
position: absolute;
left: 20px;
bottom: 18px;
}
logoutbutton {
background: transparent;
border: 1px solid rgba(255, 20, 147, 0.3);
padding: 4px 12px;
borderradius: 20px;
color: var(textsecondary);
fontsize: 11px;
fontweight: 500;
cursor: pointer;
transition: all 0.2s ease;
texttransform: uppercase;
letterspacing: 0.05em;
}
logoutbutton:hover {
color: fff;
bordercolor: var(accentblue);
background: rgba(255, 20, 147, 0.1);
boxshadow: 0 0 10px rgba(255, 20, 147, 0.3);
}
chatcontainer {
flex: 1;
overflowy: auto;
padding: calc(70px + var(safetop)) 20px 160px 20px;
display: flex;
flexdirection: column;
gap: 24px;
scrollbehavior: smooth;
webkitoverflowscrolling: touch;
}
chatcontainer::webkitscrollbar {
display: none;
}
.messagebubble {
maxwidth: 760px;
width: fitcontent;
padding: 14px 20px;
fontsize: 15px;
lineheight: 1.5;
borderradius: 22px;
position: relative;
animation: messageEnter 0.6s var(easeapple) forwards;
opacity: 0;
transform: translateY(15px);
fontweight: 300;
letterspacing: 0.01em;
boxshadow: 0 4px 15px rgba(0,0,0,0.2);
}
.messagebubble b {
fontweight: 600;
color: fff;
textshadow: 0 0 10px rgba(255,20,147,0.3);
}
@keyframes messageEnter {
to {
opacity: 1;
transform: translateY(0);
}
}
.messagebubble.ai {
alignself: flexstart;
background: rgba(40, 10, 20, 0.6);
backdropfilter: blur(20px);
webkitbackdropfilter: blur(20px);
color: var(textprimary);
border: 1px solid var(bordersubtle);
borderbottomleftradius: 4px;
boxshadow: 0 0 20px rgba(255, 20, 147, 0.1);
}
.messagebubble.user {
alignself: flexend;
background: var(accentgradient);
color: ffffff;
borderbottomrightradius: 4px;
boxshadow: 0 5px 25px rgba(255, 20, 147, 0.4);
fontweight: 400;
border: 1px solid rgba(255,255,255,0.2);
}
.messagebubble.user.hasattachments {
display: flex;
flexdirection: column;
gap: 8px;
}
.messageattachments {
display: flex;
flexwrap: wrap;
gap: 6px;
marginbottom: 4px;
}
.attachmentchip {
display: inlineflex;
alignitems: center;
gap: 4px;
background: rgba(255, 255, 255, 0.25);
padding: 4px 10px;
borderradius: 12px;
fontsize: 11px;
fontweight: 500;
border: 1px solid rgba(255,255,255,0.3);
}
.attachmentchip svg {
width: 12px;
height: 12px;
}
.attachmentchip .removeattachment {
cursor: pointer;
opacity: 0.7;
marginleft: 4px;
}
.attachmentchip .removeattachment:hover {
opacity: 1;
}
.typingindicator {
display: flex;
gap: 4px;
padding: 16px 20px;
width: fitcontent;
alignitems: center;
minheight: 44px;
}
.typingdot {
width: 6px;
height: 6px;
background: var(accentblue);
borderradius: 50%;
opacity: 0.7;
animation: typingAnimation 1.4s infinite easeinout both;
boxshadow: 0 0 8px var(accentblue);
}
.typingdot:nthchild(1) { animationdelay: 0.32s; }
.typingdot:nthchild(2) { animationdelay: 0.16s; }
@keyframes typingAnimation {
0%, 80%, 100% { transform: scale(0); opacity: 0.5; }
40% { transform: scale(1); opacity: 1; }
}
.messagebubble.streaming .cursor {
display: inlineblock;
width: 8px;
height: 15px;
background: var(accentblue);
animation: blink 1s infinite;
verticalalign: textbottom;
marginleft: 2px;
borderradius: 1px;
boxshadow: 0 0 10px var(accentblue);
}
@keyframes blink {
0%, 50% { opacity: 1; }
51%, 100% { opacity: 0; }
}
.sidebar {
position: fixed;
top: 0;
left: 0;
width: 280px;
maxwidth: 80vw;
height: 100%;
background: 0f0205;
borderright: 1px solid var(bordersubtle);
zindex: 1000;
transform: translateX(100%);
transition: transform 0.5s var(easeapple);
display: flex;
flexdirection: column;
paddingtop: var(safetop);
boxshadow: 10px 0 50px rgba(0,0,0,0.7);
}
.sidebar.open {
transform: translateX(0);
}
.sidebarheader {
display: flex;
alignitems: center;
justifycontent: spacebetween;
padding: 20px 20px;
borderbottom: 1px solid var(bordersubtle);
}
.sidebarheader h2 {
fontfamily: 'Cinzel', serif;
fontsize: 16px;
fontweight: 700;
color: var(accentblue);
texttransform: uppercase;
letterspacing: 0.1em;
