textshadow: 0 0 10px rgba(255, 20, 147, 0.4);
}
.sidebarclosebtn {
background: none;
border: none;
color: var(textsecondary);
fontsize: 20px;
cursor: pointer;
padding: 4px;
lineheight: 1;
