}
.conversationitem:hover {
background: rgba(255, 20, 147, 0.08);
bordercolor: var(bordersubtle);
boxshadow: 0 0 15px rgba(255, 20, 147, 0.1);
}
.conversationitem:active {
transform: scale(0.98);
}
.conversationitem.active {
background: rgba(255, 20, 147, 0.15);
bordercolor: var(accentblue);
boxshadow: inset 0 0 20px rgba(255, 20, 147, 0.1);
}
.conversationtitle {
fontsize: 13px;
fontweight: 400;
color: var(textprimary);
marginbottom: 4px;
whitespace: nowrap;
overflow: hidden;
textoverflow: ellipsis;
letterspacing: 0.01em;
}
.conversationdate {
fontsize: 11px;
color: var(texttertiary);
}
.conversationpreview {
fontsize: 11px;
color: var(textsecondary);
margintop: 4px;
whitespace: nowrap;
overflow: hidden;
textoverflow: ellipsis;
}
.sidebaroverlay {
position: fixed;
top: 0;
left: 0;
width: 100%;
height: 100%;
background: rgba(20, 0, 10, 0.7);
backdropfilter: blur(5px);
webkitbackdropfilter: blur(5px);
zindex: 999;
opacity: 0;
visibility: hidden;
transition: opacity 0.5s var(easeapple), visibility 0.5s var(easeapple);
}
.sidebaroverlay.visible {
opacity: 1;
visibility: visible;
}
.swipeindicator {
position: fixed;
top: 50%;
left: 0;
width: 4px;
height: 60px;
background: rgba(255, 20, 147, 0.3);
borderradius: 0 4px 4px 0;
zindex: 998;
transform: translateY(50%);
transition: all 0.3s var(easeapple);
backdropfilter: blur(10px);
border: 1px solid rgba(255, 255, 255, 0.1);
}
.swipeindicator.active {
width: 6px;
background: var(accentblue);
boxshadow: 0 0 20px rgba(255, 20, 147, 0.8);
}
.loadingconversations, .noconversations {
textalign: center;
color: var(texttertiary);
padding: 30px 20px;
fontsize: 12px;
}
.newchatbtn {
display: flex;
alignitems: center;
justifycontent: center;
gap: 8px;
margin: 12px;
padding: 12px;
background: rgba(41, 151, 255, 0.08);
color: var(accentblue);
border: 1px solid rgba(41, 151, 255, 0.15);
borderradius: 12px;
fontsize: 13px;
fontweight: 400;
